// Кейс: .qa/tests/monitoring/MON-013.md · план: .qa/e2e-app/specs/app.md (1.11)
// «בדיקת בטיחות»: уведомления (или камера) приложения выключены → строка-кнопка «הרשאות מצלמה והתרעות, אשרו…» → тап открывает Настройки iOS.
// РУЧНОЕ ПРЕДУСЛОВИЕ (разрешения ОС Appium не меняет): в настройках iPhone у приложения выключить
//   уведомления → запуск с BANCI_PERMISSION_OFF=notifications
//   камеру      → запуск с BANCI_PERMISSION_OFF=camera
// Без переменной тест пропускается. Тест в Настройках ничего не переключает. После — вручную включить обратно
// (уведомления нужны для push-тикетов, камера — для мониторинга).
import { by, assert, skip } from '../../lib/appium.mjs';
import { openSafetyCheck, waitEnabled } from '../../lib/banci.mjs';

export const name = 'בדיקת בטיחות: уведомления/камера выключены → строка «הרשאות מצלמה והתרעות, אשרו…» кнопка → тап открывает Настройки iOS (ручное предусловие BANCI_PERMISSION_OFF) #2bc13b @iphone @app @prod-safe';

const EXPECTED = {
  notifications: 'אשרו התראות בהגדרות הטלפון כדי לקבל הודעות על תקלות',
  camera: 'אשרו גישה למצלמה בהגדרות הטלפון',
};
const SETTINGS = 'com.apple.Preferences';

export default async function (app) {
  const mode = process.env.BANCI_PERMISSION_OFF;
  if (!(mode in EXPECTED)) skip('разрешения iOS меняются только вручную: выключить у приложения уведомления (или камеру) и запустить с BANCI_PERMISSION_OFF=notifications (или camera)');

  await openSafetyCheck(app);

  // 1. Строка с подсказкой — кнопка.
  const row = await app.waitFor(by.contains(EXPECTED[mode], 'Button'), {
    timeout: 20000,
    what: `строка-кнопка «הרשאות מצלמה והתרעות, ${EXPECTED[mode]}» (BANCI_PERMISSION_OFF=${mode})`,
  });

  // 2. Пока строка с ⚠ — «המשך» серая.
  const next = await app.waitFor(by.exact('המשך', 'Button'), { what: '«המשך»' });
  await waitEnabled(next, false, { timeout: 5000, what: '«המשך» при выключенном разрешении' });

  // 3. Тап по строке → Настройки iOS на переднем плане (страница приложения).
  await row.click();
  const end = Date.now() + 10000;
  let state;
  while (Date.now() < end) {
    state = await app.appState(SETTINGS);
    if (state === 4) break;
    await new Promise((r) => setTimeout(r, 300));
  }
  assert(state === 4, `после тапа по строке открылись Настройки iOS (${SETTINGS} на переднем плане), сейчас queryAppState=${state}`);

  // 4. Назад в приложение, ничего не переключая.
  await app.activate();
  await app.waitFor(by.contains('בדיקת בטיחות'), { timeout: 15000, what: 'возврат в приложение на «בדיקת בטיחות»' });
  await app.restart();
}
